import{_ as o,C as n,o as t,c as s,a2 as r,b as l,w as a,a as c,E as d,a3 as u}from"./chunks/framework.Brv5O9VI.js";const _=JSON.parse('{"title":"14.11 Security Architecture & Air-Gap Defense","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.11-security-architecture.md","filePath":"system-design/14.11-security-architecture.md"}'),h={name:"system-design/14.11-security-architecture.md"};function p(g,e,m,y,f,b){const i=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=r('<h1 id="_14-11-security-architecture-air-gap-defense" tabindex="-1">14.11 Security Architecture &amp; Air-Gap Defense <a class="header-anchor" href="#_14-11-security-architecture-air-gap-defense" aria-label="Permalink to &quot;14.11 Security Architecture &amp; Air-Gap Defense&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Security architecture defines the defense-in-depth principles—perimeter controls, identity verification, transport encryption, and data sanitization—that protect a system from data breaches, code injection, and unauthorized tampering.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><p>The platform implements an <strong>Air-Gapped, Zero-Outbound Security Architecture</strong>:</p><ul><li><strong>Zero Cloud API Dependence</strong>: The backend makes zero outbound requests to cloud AI services (OpenAI, AWS, Anthropic).</li><li><strong>Network Isolation</strong>: Operates with zero internet connectivity once containerized.</li><li><strong>Input Validation Sanitization</strong>: All incoming payloads are strictly typed and parsed via Pydantic v2 ([<code>app.py:L61-L67</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L61-L67)).</li><li><strong>Domain Guardrail Filtering</strong>: Protects the regulatory boundary via a deterministic 4-tier filter in [<code>guardrail.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/guardrail.py).</li></ul>',7)),(t(),l(u,null,{default:a(()=>[d(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20UntrustedClient%5B%22Client%20on%20Internal%20%2F%20Public%20Network%22%5D%20--%3E%20Firewall%5B%22Perimeter%20Firewall%20%2F%20Nginx%20Reverse%20Proxy%22%5D%0A%20%20%20%20Firewall%20--%3E%7CTLS%201.3%20Encryption%7C%20CORSFilter%5B%22CORS%20Domain%20Validation%22%5D%0A%20%20%20%20CORSFilter%20--%3E%20Pydantic%5B%22Pydantic%20Payload%20Validation%22%5D%0A%20%20%20%20Pydantic%20--%3E%20Guardrail%5B%224-Tier%20Regulatory%20Guardrail%20(guardrail.py)%22%5D%0A%20%20%20%20Guardrail%20--%3E%20AirGapSandbox%5B%22Air-Gapped%20Memory%20Sandbox%20(FAISS%20%2B%20FastEmbed)%22%5D%0A%20%20%20%20%0A%20%20%20%20style%20AirGapSandbox%20fill%3A%23064e3b%2Cstroke%3A%2310b981%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="_3-comparison-with-security-models" tabindex="-1">3. Comparison with Security Models <a class="header-anchor" href="#_3-comparison-with-security-models" aria-label="Permalink to &quot;3. Comparison with Security Models&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Security Control</th><th style="text-align:left;">Cloud-Dependent AI Architecture</th><th style="text-align:left;">Air-Gapped Local Architecture (Used)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Data Leakage Risk</strong></td><td style="text-align:left;">High (User queries transmitted to third-party cloud servers)</td><td style="text-align:left;"><strong>Zero (Vectors remain in local host RAM)</strong></td></tr><tr><td style="text-align:left;"><strong>Prompt Injection Risk</strong></td><td style="text-align:left;">Severe (LLM jailbreaks can leak instructions or bypass filters)</td><td style="text-align:left;"><strong>Immune (No generative LLM; deterministic vector search)</strong></td></tr><tr><td style="text-align:left;"><strong>Secret Management Risk</strong></td><td style="text-align:left;">High (API keys in <code>.env</code> or CI/CD pipelines can be compromised)</td><td style="text-align:left;"><strong>Zero (No API keys or external credentials exist)</strong></td></tr><tr><td style="text-align:left;"><strong>Compliance Overhead</strong></td><td style="text-align:left;">High (Requires DPDP/GDPR third-party vendor audits)</td><td style="text-align:left;"><strong>Minimal (100% data residency compliance)</strong></td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Public Internal Access</strong>: In its default configuration, any user with network access to port 8000 can invoke <code>/chat</code> because user authentication and role-based access control (RBAC) are not yet integrated.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Security posture remains sound.</li><li><strong>At 100x Load</strong>: Lack of authentication prevents attributing which user or department generated a specific audit pack.</li><li><strong>At 1000x Load</strong>: Lack of IP-based rate limiting allows brute-force resource exhaustion.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><ol><li>Integrate <strong>JWT-based RBAC</strong> using OAuth 2.0 with asymmetric RSA keys (RS256).</li><li>Escape all user-supplied text strings in CSV generation to neutralize CSV formula injection (<code>=</code>, <code>+</code>, <code>-</code>, <code>@</code>).</li><li>Restrict <code>CORSMiddleware</code> from <code>allow_origins=[&quot;*&quot;]</code> to explicit enterprise domain origins.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Our security architecture is built on complete air-gap isolation: because FastEmbed and FAISS execute locally in memory, no proprietary manufacturing blueprints or product queries are ever transmitted over external networks. Furthermore, because we use deterministic vector retrieval rather than an autoregressive LLM, our engine is mathematically immune to prompt injection attacks.&quot;</p></blockquote>',15))])}const S=o(h,[["render",p]]);export{_ as __pageData,S as default};
